import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import lmb_bpy

scene = lmb_bpy.Scene()
textured = scene.uv_sphere(0.88, 48, 24, True)
textured.translate(-1.15, 0.0, 0.90)
