scene.ground_plane(0.0, 28.0, 0.25, 0.27, 0.30)
scene.area_light_shape(-3.8, -4.5, 6.5, 0.0, 0.0, 0.8, 1.0, 0.86, 0.72, 620.0, 4.8, 3.2, "rectangle")
